const POSTED_ICON = "data:image/png;base64,";

function Mark({ size = 26 }) {
  return <img src={POSTED_ICON} alt="Posted" style={{ height: size, width: size * 0.89 }} draggable={false} />;
}
function Wordmark({ light }) {
  return (
    <div className="flex items-center gap-2 select-none">
      <Mark size={26} />
      <span style={{ fontFamily: "-apple-system,BlinkMacSystemFont,'Helvetica Neue',Arial,sans-serif", fontWeight: 700, fontSize: 22, color: light ? "#fff" : "#111", letterSpacing: "-0.01em" }}>Posted</span>
    </div>
  );
}
function Carrots({ n }) {
  return <span className="inline-flex items-center gap-1 font-semibold" style={{ color: "#B45309" }}><Carrot size={14} /> {n.toLocaleString()}</span>;
}

